	[Fact]
	public void AllEighteenVariantsPreserveFrozenGeometryDimensionsAndAccessibility()
	{
		using var context = new ComponentTestContext(_ => throw new InvalidOperationException("Icons never fetch data"));
		Assert.Equal(18, approved.Count);
		foreach ((string name, string svg) in approved)
		{
			var icon = context.Render<AppIcon>(parameters => parameters.Add(component => component.Name, name));
			Assert.Single(icon.FindAll("svg"));
			Assert.Equal(Normalize(XElement.Parse(svg)), Normalize(XElement.Parse(icon.Markup)));
		}
	}

	private static string Normalize(XElement element) => element.Name.LocalName + "[" + string.Join(";", element.Attributes().OrderBy(attribute => attribute.Name.LocalName).Select(attribute => attribute.Name.LocalName + "=" + attribute.Value)) + "]" + string.Concat(element.Elements().Select(Normalize));
}
